from physics_sl_common import *
Q=[];topic='wave-behaviour'
for i in range(4):
 omega2=16+9*i;amplitude=.04+.01*i;period=2*math.pi/math.sqrt(omega2);rows=[(x,round(-omega2*x,5)) for x in [-.04,-.02,0,.02,.04]]
 Q.append(rec(topic,0,i,'Testing a restoring-acceleration model','C.1',rf'A sensor provides the following simulated acceleration-displacement readings for an oscillator. Displacement is measured from equilibrium. Its amplitude is ${amplitude:.3f}\,\mathrm{{m}}$.'+table(['$x$ / m',r'$a$ / $\mathrm{m\,s^{-2}}$'],rows),[P('Explain why the readings are consistent with simple harmonic motion.',R('Acceleration is proportional to displacement in magnitude.'),R('The acceleration has the opposite sign to displacement and is directed towards equilibrium.')),P('Find the angular frequency and period.',M(r'Compare the gradient with $a=-\omega^2x$.'),A(rf'$\omega={fmt(math.sqrt(omega2))}\,\mathrm{{rad\,s^{{-1}}}}$.'),A(rf'$T={fmt(period)}\,\mathrm{{s}}$.')),P('Find the maximum acceleration magnitude.',M(r'$a_\mathrm{max}=\omega^2A$.'),A(rf'${fmt(omega2*amplitude)}\,\mathrm{{m\,s^{{-2}}}}$.')),P('Explain why zero acceleration does not imply zero velocity in this motion.',R('Acceleration is zero at equilibrium, where the oscillator passes through with its greatest speed; acceleration describes a change in velocity.'))],f'Signed gradient from all rows is−{omega2}s−2; positive frequency square root; T={period}; maxaccel={omega2*amplitude}. SL restoring relation only.',difficulty='medium'))
 wavelength=.40+.10*i;T=.020+.005*i;Amm=3+i;v=wavelength/T
 body=text(70,24,'Snapshot at one instant: displacement / mm')
 for offset,span,label in [(0,wavelength*2,'position / m'),(205,T*2,'time / s at one fixed point')]:
  y0=110+offset;body+=line(75,y0,590,y0)+line(75,y0-65,75,y0+65)+text(595,y0+87,label,14,'end')
  pts=[(75+500*k/160,y0-50*math.sin(4*math.pi*k/160)) for k in range(161)]
  body+='<polyline points="'+' '.join(f'{x:.2f},{y:.2f}' for x,y in pts)+'" fill="none" stroke="#7a1f24" stroke-width="2"/>'
  for k in range(5):body+=line(75+125*k,y0-4,75+125*k,y0+4)+text(75+125*k,y0+73,f'{span*k/4:.4g}',12,'middle')
  body+=text(60,y0-45,Amm,12,'end')+text(60,y0+5,'0',12,'end')+text(60,y0+55,-Amm,12,'end')
 body+=text(70,229,'Time trace: displacement / mm')
 Q.append(rec(topic,1,i,'Reading two complementary wave traces','C.2',r'The upper diagram is a spatial snapshot of a transverse wave. The lower diagram records one particle as a function of time. Both have the same displacement scale. The wave travels without changing shape.',[P('Read the amplitude and wavelength.',A(rf'Amplitude ${Amm}.00\,\mathrm{{mm}}$.'),A(rf'Wavelength ${fmt(wavelength)}\,\mathrm{{m}}$.')),P('Determine the period and frequency.',A(rf'Period ${fmt(T)}\,\mathrm{{s}}$.'),M(r'$f=1/T$.'),A(rf'$f={fmt(1/T)}\,\mathrm{{Hz}}$.')),P('Calculate the wave speed.',M(r'$v=f\lambda$.'),A(rf'$v={fmt(v)}\,\mathrm{{m\,s^{{-1}}}}$.')),P('Explain why the graph does not show a particle travelling along the medium at this speed.',R('Particles oscillate about fixed equilibrium positions transverse to propagation, while the disturbance and energy travel along the medium.'))],f'Generated two complete sinusoidal cycles across2λ and2T with explicit positive/negative displacement axes; λ={wavelength},T={T},v={v}. No phase calculation required.',diagram=svg(body,660,430),difficulty='easy'))
 lam=(500+20*i)*1e-9;d=(.25+.05*i)*1e-3;D=1.5+.2*i;spacing=lam*D/d;five=5*spacing;unc=.02/five/1000 # length uncertainty 0.02 mm
 Q.append(rec(topic,2,i,'A double-slit measurement across several fringes','C.3',rf'Monochromatic light illuminates two narrow coherent slits separated by ${fmt(d)}\,\mathrm{{m}}$. A screen is ${D:.2f}\,\mathrm{{m}}$ from the slits. In a simulated measurement the distance from the centre of one bright fringe to the centre of the fifth next bright fringe is ${five*1000:.6f}\pm0.020\,\mathrm{{mm}}$. The slit separation and screen distance have negligible uncertainty. Small-angle conditions apply.',[P('Determine the adjacent bright-fringe separation.',M('Divide the measured distance by five intervals.'),A(rf'$s={fmt(spacing)}\,\mathrm{{m}}$.')),P('Calculate the wavelength.',M(r'$s=\lambda D/d$, so $\lambda=sd/D$.'),A(rf'$\lambda={fmt(lam)}\,\mathrm{{m}}$.')),P('Estimate the absolute wavelength uncertainty, giving two significant figures.',M('Only the measured fringe distance contributes, so its fractional uncertainty equals the fractional wavelength uncertainty.'),A(rf'$\Delta\lambda={fmt(lam*unc,2)}\,\mathrm{{m}}$.')),P('Explain why coherent sources are needed for a stable pattern.',R('They maintain a constant phase difference.'),R('Constructive and destructive interference therefore remain at fixed positions rather than averaging away.')),P('Predict the change in adjacent-fringe separation if the screen distance is doubled.',R('It doubles, provided the small-angle approximation remains valid.'))],f'Measured five-interval distance displayed6dp; λ=dL/(5D)={lam}; linear uncertainty={lam*unc}; no single-slit/grating AHL demand.',difficulty='hard'))
 length=.60+.10*i;c=330+5*i;f1=c/(4*length);fnext=3*f1
 drawing=svg(line(140,110,550,110)+line(140,235,550,235)+line(140,110,140,235)+text(140,87,'closed end')+text(550,87,'open end',16,'end')+text(345,275,f'length = {length:.2f} m',16,'middle')+text(345,320,'Longitudinal air displacement is considered',15,'middle'))
 Q.append(rec(topic,3,i,'Allowed modes of a closed-open air column','C.4',rf'A tube of length ${length:.2f}\,\mathrm{{m}}$ is closed at one end and open at the other. Sound speed is ${c}\,\mathrm{{m\,s^{{-1}}}}$. Neglect end corrections.',[P('State the displacement boundary condition at each end.',R('The closed end is a displacement node.'),R('The open end is a displacement antinode.')),P('Find the first harmonic wavelength and frequency.',M(r'The first harmonic has one quarter wavelength in the tube: $\lambda_1=4L$.'),A(rf'$\lambda_1={fmt(4*length)}\,\mathrm{{m}}$.'),A(rf'$f_1={fmt(f1)}\,\mathrm{{Hz}}$.')),P('Find the next allowed resonance frequency and explain why twice the first harmonic is not allowed.',A(rf'$f_3=3f_1={fmt(fnext)}\,\mathrm{{Hz}}$.'),R('The next closed-open displacement mode fits three quarters of a wavelength; even harmonics do not satisfy both boundary conditions.')),P('The tube is driven near a resonance. Explain the large amplitude.',R('The driving frequency is close to a natural frequency, so energy is transferred efficiently to that mode over repeated cycles.'))],f'Fixed-free boundary conditions; allowedfirst harmonicλ=4L, nextλ=4L/3; frequencies{f1},{fnext}. Explicit displacement modes avoid excluded pressure-node/end-correction content.',diagram=drawing,difficulty='medium'))
 rest=480+20*i;shift=2.4+.4*i;observed=rest+shift;cLight=3e8;beta=shift/rest;radial=cLight*beta;frequency=cLight/(observed*1e-9)
 Q.append(rec(topic,4,i,'Interpreting a shifted spectral line','C.5',rf'A distant source emits a spectral line whose laboratory wavelength is ${rest:.2f}\,\mathrm{{nm}}$. Its observed wavelength is ${observed:.2f}\,\mathrm{{nm}}$. Assume the shift is caused entirely by radial source motion, with speed much smaller than $c=3.00\times10^8\,\mathrm{{m\,s^{{-1}}}}$.',[P('State whether the source approaches or recedes, with a reason.',R('It recedes, because the observed wavelength is longer than the laboratory wavelength.')),P('Calculate the wavelength shift and the radial speed.',A(rf'$\Delta\lambda={fmt(shift)}\,\mathrm{{nm}}$.'),M(r'For the stated low-speed model, $\Delta\lambda/\lambda_0\simeq v/c$.'),A(rf'$v={fmt(radial)}\,\mathrm{{m\,s^{{-1}}}}$.')),P('Calculate the observed frequency.',M(r'$f=c/\lambda_\mathrm{observed}$ with wavelength in metres.'),A(rf'$f={fmt(frequency)}\,\mathrm{{Hz}}$.')),P('Explain why the measurement alone cannot determine the full speed in three dimensions.',R('The spectral shift gives the velocity component along the line of sight, so an unknown transverse component is not measured.')),P('Discuss whether the low-speed assumption is self-consistent.',R(rf'$v/c={fmt(beta)}\ll1$; this supports using the stated approximation.'))],f'Positive redshift{shift}nm, β={beta}<0.007; uses SL smallshift EM relation, no acoustic moving-source equation. Frequency={frequency}.',difficulty='medium'))
save(topic,Q)
print('Physics SL Theme C additions20 authored.')
